"""Temporary functional workspace. Original C2 CSS/layout port follows validation."""
HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Janshakti | C2 Test Workspace</title>
<style nonce="{{ g.csp_nonce }}">
*{box-sizing:border-box}body{margin:0;background:#f4f6f8;color:#193449;font:15px system-ui,sans-serif}header{background:#17364d;color:white;padding:14px 24px;display:flex;align-items:center;gap:18px;flex-wrap:wrap}header h1{font-size:20px;margin:0}header small{margin-left:auto}main{display:grid;grid-template-columns:225px minmax(0,1fr);min-height:calc(100vh - 65px)}nav{background:white;border-right:1px solid #d9e2e8;padding:14px;display:flex;flex-direction:column;gap:6px}nav button{text-align:left;border:0;background:#f5f7fa}nav button.current{background:#dcebf4;color:#17364d;font-weight:bold}article{padding:24px;min-width:0}#signin{max-width:440px;margin:60px auto;background:white;padding:24px;border:1px solid #d9e2e8;border-radius:10px}input,select,textarea,button{font:inherit;border:1px solid #b9c6d0;padding:9px;border-radius:5px;max-width:100%}button{cursor:pointer;background:white;color:#17364d}button.primary{background:#17364d;color:white}button:disabled{opacity:.55;cursor:wait}label{display:flex;flex-direction:column;gap:4px;font-size:13px;min-width:120px}form{display:flex;align-items:end;flex-wrap:wrap;gap:10px}#signin form{display:grid}h2{margin:0 0 14px}h3{margin:14px 0 8px}p{line-height:1.45}.panel{background:white;border:1px solid #d9e2e8;border-radius:8px;padding:16px;margin:12px 0}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px}.metric{background:white;border:1px solid #d9e2e8;border-radius:8px;padding:16px}.metric strong{display:block;font-size:28px;margin-top:6px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border-bottom:1px solid #e0e7ed;padding:9px;text-align:left;white-space:nowrap}th{background:#eaf0f5}td button{margin-right:6px}#status{white-space:pre-wrap;margin:10px 0;color:#344e62}#status.error{color:#9b2424}a{color:inherit}.notice{color:#53687a;font-size:13px}[hidden]{display:none!important}@media(max-width:760px){main{grid-template-columns:1fr}nav{flex-direction:row;overflow:auto;border-bottom:1px solid #d9e2e8}nav button{white-space:nowrap}article{padding:12px}}
</style></head><body>
<header><h1>JAN SHAKTI · Inventory &amp; Work Orders</h1><small>TEST WORKSPACE · Synthetic data only</small><span id="who"></span><button id="out" hidden>Sign out</button></header>
<section id="signin"><h2>Application login</h2><p>Sign in with your existing application account.</p><form id="login"><label>Username<input name="username" autocomplete="username" required></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button class="primary">Sign in</button></form><p id="loginmsg" role="status"></p><a href="/preview">Existing report preview</a></section>
<main id="workspace" hidden><nav id="nav"></nav><article><h2 id="heading"></h2><p class="notice" id="note"></p><div id="content"></div><p id="status" role="status"></p></article></main>
<script nonce="{{ g.csp_nonce }}">
'use strict';
let token='',me=null,page='',generation=0,busy=false;
const $=id=>document.getElementById(id), content=$('content'), status=$('status');
const el=(tag,text,cls)=>{let n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
function msg(s,error=false){status.textContent=s;status.className=error?'error':''}
function field(form,name,label,options={}){let l=el('label',label),n;if(options.values){n=el('select');for(const v of options.values)n.append(new Option(v,v))}else{n=el(options.area?'textarea':'input');if(!options.area)n.type=options.type||'text';if(options.max)n.maxLength=options.max}n.name=name;n.required=!!options.required;if(options.value!==undefined)n.value=options.value;l.append(n);form.append(l);return n}
function button(parent,text,fn,primary=false){let b=el('button',text,primary?'primary':'');b.type='button';b.onclick=fn;parent.append(b);return b}
function submit(form,text){let b=el('button',text,'primary');b.type='submit';form.append(b);return b}
function panel(title){let p=el('section',undefined,'panel');if(title)p.append(el('h3',title));content.append(p);return p}
function formAt(p){let f=el('form');p.append(f);return f}
function table(p,rows,actions){let wrapper=el('div',undefined,'scroll');p.append(wrapper);if(!rows.length){wrapper.append(el('p','No matching records.'));return}let cols=Object.keys(rows[0]).filter(k=>k!=='id'&&k!=='rowVersion');let t=el('table'),head=el('thead'),tr=el('tr');for(let k of cols)tr.append(el('th',k));if(actions)tr.append(el('th','Actions'));head.append(tr);t.append(head);let body=el('tbody');for(let row of rows){let r=el('tr');for(let k of cols)r.append(el('td',row[k]??''));if(actions){let cell=el('td');actions(cell,row);r.append(cell)}body.append(r)}t.append(body);wrapper.append(t)}
function formData(f){return Object.fromEntries(new FormData(f))}
const has=p=>['View','Edit'].includes(me?.grants[p]), edit=p=>me?.grants[p]==='Edit';
async function call(path,opt={}){let r=await fetch(path,{...opt,headers:{'Content-Type':'application/json','Authorization':'Bearer '+token}});if(!r.ok){let d=await r.json().catch(()=>({}));throw Error(d.error||'Request failed ('+r.status+')')}return r}
async function get(path){return (await call(path)).json()}
async function post(path,data){return (await call(path,{method:'POST',body:JSON.stringify(data)})).json()}
function run(fn){return async e=>{e?.preventDefault();if(busy)return;let g=generation;busy=true;try{msg('Working…');await fn(g)}catch(err){if(g===generation)msg(err.message,true)}finally{busy=false}}}
function current(g){return g===generation&&!!token}
const notes={'Dashboard':'Live on-hand stock and aging quantities; cost values not displayed.','Product Master':'Create, edit or archive purchased products. Unique models, linked-history checks and revision conflicts are enforced.','Work Orders':'Read-only work order line view. Versioned creation, revision and Hold/Cancel workflows are not enabled yet.','Work Order Tracker':'Read-only stage history. Stage changes and packing gates are not enabled yet.','Stock In':'History and new free Bought Out receipts only. Work-order-linked and fabrication receipts are not enabled yet.','Stock Out':'Read-only dispatch history. Dispatch and reversal writes are not enabled yet.','Stock Book':'Available physical units, searchable by serial, product, location and work order.','Reports':'Authorized Excel exports. Bulk edit/import and full original report parity are pending.','Superadmin':'Create operator accounts, set passwords, enable/disable accounts and assign explicit permissions. No direct SQL editor or admin escalation.'};
function pages(){let a=[];for(let p of ['Dashboard','Work Orders','Work Order Tracker','Stock In','Stock Out','Stock Book','Product Master'])if(has(p)&&me.routes.length&&(p!=='Product Master'||me.routes.includes('Bought Out')))a.push(p);if(has('Report'))a.push('Reports');if(me.admin)a.push('Superadmin');return a}
function navigation(){let n=$('nav');n.replaceChildren();for(let p of pages()){let b=button(n,p,()=>open(p));if(p===page)b.classList.add('current')}let link=el('a','Legacy report preview');link.href='/preview';n.append(link)}
async function open(p){generation++;let g=generation;page=p;navigation();$('heading').textContent=p;$('note').textContent=notes[p]||'';content.replaceChildren();msg('');try{if(p==='Dashboard')await dashboard(g);else if(p==='Product Master')await productPage(g);else if(p==='Reports')await reports(g);else if(p==='Superadmin')await admin(g);else await history(g)}catch(e){if(current(g))msg(e.message,true)}}
$('login').onsubmit=async e=>{e.preventDefault();let m=$('loginmsg');m.textContent='Signing in…';try{let form=e.currentTarget,data=formData(form),r=await post('/api/login',data);token=r.token;form.reset();me=await get('/api/c2/me');$('signin').hidden=true;$('workspace').hidden=false;$('out').hidden=false;$('who').textContent=me.username+(me.admin?' · Superadmin':'');let p=pages()[0];if(p)await open(p);else{navigation();$('heading').textContent='No assigned pages';content.replaceChildren()}}catch(err){token='';me=null;m.textContent=err.message}};
$('out').onclick=async()=>{generation++;try{await call('/api/logout',{method:'POST'})}catch(e){}finally{token='';me=null;content.replaceChildren();$('workspace').hidden=true;$('out').hidden=true;$('who').textContent='';$('signin').hidden=false;$('loginmsg').textContent='Signed out'}};
async function dashboard(g){let d=await get('/api/c2/dashboard');if(!current(g))return;let cards=el('div',undefined,'cards');content.append(cards);for(let [label,key] of [['Physical stock','physical'],['Free stock','free'],['Engaged stock','engaged'],['Critical free','critical']]){let c=el('div',label,'metric');c.append(el('strong',d[key].qty));cards.append(c)}table(panel('Warehouse stock'),d.byLocation);table(panel('Inventory aging'),d.aging);button(panel(),'Refresh',()=>open('Dashboard'))}
async function productPage(g){let editor=panel('Product details'),f=formAt(editor);let name=field(f,'name','Equipment name',{required:true,max:200}),kind=field(f,'type','Product type',{values:['STD','Spare','Other']}),brand=field(f,'brand','Brand',{required:true,max:100}),model=field(f,'model','Model',{required:true,max:100}),size=field(f,'size','Size / capacity',{max:200});let selected=null;let canEdit=edit('Product Master')&&edit('Route: Bought Out');editor.hidden=!canEdit;submit(f,'Save product');button(f,'New / clear',()=>{selected=null;f.reset()});f.onsubmit=run(async gen=>{let data=formData(f);await post('/api/c2/products',{...data,action:selected?'update':'create',id:selected?.productId||'',version:selected?.rowVersion||0});if(current(gen)){selected=null;f.reset();await open('Product Master');msg('Product saved')}});let p=panel('Product search'),search=formAt(p);field(search,'q','Search equipment, model, brand',{max:100});submit(search,'Search');let list=el('div');p.append(list);async function load(after=''){let r=await get('/api/c2/products?'+new URLSearchParams({...formData(search),after}));if(!current(g))return;list.replaceChildren();table(list,r.products,canEdit?(cell,row)=>{button(cell,'Edit',()=>{selected=row;name.value=row.equipmentName;kind.value=row.productType;brand.value=row.brand;model.value=row.model;size.value=row.sizeCapacity;name.focus()});if(edit('Delete Products'))button(cell,'Archive',run(async gen=>{if(!confirm('Archive '+row.productId+'?'))return;await post('/api/c2/products',{action:'archive',id:row.productId,version:row.rowVersion});if(current(gen)){await open('Product Master');msg('Product archived')}}))}:null);if(r.next)button(list,'Next page',()=>load(r.next).catch(e=>msg(e.message,true)))}search.onsubmit=run(async()=>{await load();msg('Search complete')});await load()}
async function history(g){if(page==='Stock In'&&edit('Stock In')&&edit('Route: Bought Out')){let p=panel('New free Bought Out receipt'),f=formAt(p);field(f,'product','Product ID (from Product Master)',{required:true,max:100});field(f,'location','Location',{values:['Bapu Nagar warehouse','Bakrol warehouse','Bapu Nagar showroom']});field(f,'date','Receipt date',{type:'date',required:true,value:new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'})});field(f,'qty','Quantity',{type:'number',required:true,value:'1'});field(f,'serials','Serials (one per line)',{area:true,required:true,max:10100});field(f,'cost','Unit purchase cost',{required:true,max:30});field(f,'vendor','Vendor',{max:140});field(f,'remarks','Remarks',{max:600});submit(f,'Receive free stock');f.onsubmit=run(async gen=>{let data=formData(f);data.qty=Number(data.qty);data.serials=data.serials.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);let r=await post('/api/c2/receive-free',data);if(current(gen)){await open('Stock In');msg('Receipt saved: '+r.id)}})}let p=panel('Search and date filters'),f=formAt(p),thisPage=page;field(f,'q','Search',{max:100});field(f,'from','From',{type:'date'});field(f,'to','To',{type:'date'});submit(f,'Apply filters');let rows=el('div');p.append(rows);async function load(after=''){let r=await get('/api/c2/page?'+new URLSearchParams({...formData(f),page:thisPage,after}));if(!current(g))return;rows.replaceChildren();table(rows,r.rows);if(r.next)button(rows,'Next page',()=>load(r.next).catch(e=>msg(e.message,true)))}f.onsubmit=run(async()=>{await load();msg('Search complete')});await load()}
async function reports(g){let catalog=await get('/api/reports');if(!current(g))return;let f=formAt(panel('Download Excel')),select=field(f,'key','Report',{values:[]});for(let [k,v] of Object.entries(catalog))select.append(new Option(v,k));for(let [k,v] of [['workOrder','Work Order'],['product','Product / model / serial'],['location','Location']])field(f,k,v,{max:100});field(f,'from','From',{type:'date'});field(f,'to','To',{type:'date'});let b=submit(f,'Download Excel');if(!select.options.length)b.disabled=true;f.onsubmit=run(async gen=>{let data=formData(f),key=data.key;delete data.key;let r=await call('/api/reports/'+encodeURIComponent(key),{method:'POST',body:JSON.stringify(data)});let blob=await r.blob();if(!current(gen))return;let url=URL.createObjectURL(blob),a=el('a','Download');a.href=url;a.download='Janshakti-'+key+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);msg('Excel downloaded')})}
async function admin(g){let create=formAt(panel('Create an operator')),u=field(create,'username','Username',{required:true,max:80});field(create,'password','Initial private password',{type:'password',required:true,max:72});submit(create,'Create account');create.onsubmit=run(async gen=>{let d=formData(create);await post('/api/c2/admin/users',{action:'create',...d});if(current(gen)){create.reset();await open('Superadmin');msg('Account created; assign permissions before use')}});let p=panel('User accounts and access matrix');let list=el('div');p.append(list);async function load(after=''){let data=await get('/api/c2/admin/users?'+new URLSearchParams({after}));if(!current(g))return;list.replaceChildren();for(let row of data.users){let card=el('section',undefined,'panel');list.append(card);card.append(el('h3',row.username+' · '+(row.active?'Active':'Disabled')+' · '+(row.team||'Operator')));if(row.team==='Admin'||row.grants.Superadmin&&row.grants.Superadmin!=='None'||row.username===me.username){card.append(el('p','Protected administrator. Manage elevated roles only through authorized database owner.'));continue}let access=el('p',Object.entries(row.grants).filter(([k,v])=>v!=='None').map(([k,v])=>k+': '+v).join(' · ')||'No active grants');card.append(access);let f=formAt(card),perm=field(f,'permission','Permission',{values:me.permissions}),level=field(f,'level','Access',{values:['None','View','Edit']});perm.onchange=()=>level.value=row.grants[perm.value]||'None';perm.onchange();submit(f,'Save permission');f.onsubmit=run(async gen=>{await post('/api/c2/admin/users',{action:'grant',username:row.username,...formData(f)});if(current(gen)){await open('Superadmin');msg('Permission saved')}});let reset=formAt(card);field(reset,'password','New private password',{type:'password',required:true,max:72});submit(reset,'Reset password');reset.onsubmit=run(async gen=>{await post('/api/c2/admin/users',{action:'reset',username:row.username,...formData(reset)});reset.reset();if(current(gen))msg('Password reset; old sessions revoked')});button(card,row.active?'Disable':'Enable',run(async gen=>{if(!confirm('Change account status for '+row.username+'?'))return;await post('/api/c2/admin/users',{action:'active',username:row.username,active:!row.active});if(current(gen)){await open('Superadmin');msg('Account status updated')}}))}if(data.next)button(list,'Next page',()=>load(data.next).catch(e=>msg(e.message,true)))}await load()}
</script></body></html>'''
